import { HTMLProps } from 'react';
import type * as Stitches from '@stitches/react';
import { config } from '@hexa-ui/theme';

type CSSCardVariants = Stitches.CSS<typeof config>;
export interface CardTypes extends Omit<HTMLProps<HTMLDivElement>, 'ref'> {
  /** This property is responsible for the box shadowing elevation */
  elevated: 'minimal' | 'small' | 'medium' | 'large' | 'xlarge';
  /** This property is responsible for the border radius size */
  border: 'none' | 'small' | 'medium' | 'large';
  css?: CSSCardVariants;
}
